#include <bits/stdc++.h>
using namespace std;

const int mod = 998244353;
const int g = 3;

long long qpow(long long base, long long exp) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

void bitReverse(vector<long long>& array, int length) {
    for (int i = 1, j = 0; i < length; i++) {
        int bit = length >> 1;
        while (j >= bit) {
            j -= bit;
            bit >>= 1;
        }
        j += bit;
        if (i < j) {
            swap(array[i], array[j]);
        }
    }
}

void transform(vector<long long>& array, int length, int direction) {
    bitReverse(array, length);
    for (int size = 2; size <= length; size <<= 1) {
        long long root = qpow(g, (mod - 1) / size);
        if (direction == -1) root = qpow(root, mod - 2);
        for (int start = 0; start < length; start += size) {
            long long w = 1;
            for (int k = start; k < start + size / 2; k++) {
                long long u = array[k];
                long long v = array[k + size / 2] * w % mod;
                array[k] = (u + v) % mod;
                array[k + size / 2] = (u - v + mod) % mod;
                w = w * root % mod;
            }
        }
    }
    if (direction == -1) {
        long long invLen = qpow(length, mod - 2);
        for (int i = 0; i < length; i++) {
            array[i] = array[i] * invLen % mod;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    int len = 1;
    int halfN = n / 2;
    while (len < (9 * halfN + 1)) len <<= 1;
    vector<long long> array(len, 0);
    for (int i = 0; i < m; i++) {
        int x;
        cin >> x;
        array[x] = 1;
    }
    transform(array, len, 1);
    for (int i = 0; i < len; i++) {
        if (array[i] != 0) {
            array[i] = qpow(array[i], halfN) % mod;
        }
    }
    transform(array, len, -1);
    long long total = 0;
    for (int i = 0; i < len; i++) {
        total = (total + array[i] * array[i]) % mod;
    }
    cout << total << "\n";
    return 0;
}
